CELLS = ['from d2l import torch as d2l\nimport torch\nfrom torch import nn\n\nbatch_size, num_steps = 32, 35\ntrain_iter, vocab = d2l.load_data_time_machine(batch_size, num_steps)\n', 'def get_params(vocab_size, num_hiddens, device):\n    num_inputs = num_outputs = vocab_size\n\n    def normal(shape):\n        return torch.randn(size=shape, device=device)*0.01\n\n    def three():\n        return (normal((num_inputs, num_hiddens)),\n                normal((num_hiddens, num_hiddens)),\n                d2l.zeros(num_hiddens, device=device))\n\n    W_xz, W_hz, b_z = three()  # 更新门参数\n    W_xr, W_hr, b_r = three()  # 重置门参数\n    W_xh, W_hh, b_h = three()  # 候选隐状态参数\n    # 输出层参数\n    W_hq = normal((num_hiddens, num_outputs))\n    b_q = d2l.zeros(num_outputs, device=device)\n    # 附加梯度\n    params = [W_xz, W_hz, b_z, W_xr, W_hr, b_r, W_xh, W_hh, b_h, W_hq, b_q]\n    for param in params:\n        param.requires_grad_(True)\n    return params\n', 'def init_gru_state(batch_size, num_hiddens, device):\n    return (torch.zeros((batch_size, num_hiddens), device=device), )\n', 'def gru(inputs, state, params):\n    W_xz, W_hz, b_z, W_xr, W_hr, b_r, W_xh, W_hh, b_h, W_hq, b_q = params\n    H, = state\n    outputs = []\n    for X in inputs:\n        Z = torch.sigmoid((X @ W_xz) + (H @ W_hz) + b_z)\n        R = torch.sigmoid((X @ W_xr) + (H @ W_hr) + b_r)\n        H_tilda = torch.tanh((X @ W_xh) + ((R * H) @ W_hh) + b_h)\n        H = Z * H + (1 - Z) * H_tilda\n        Y = H @ W_hq + b_q\n        outputs.append(Y)\n    return torch.cat(outputs, dim=0), (H,)\n', 'def get_lstm_params(vocab_size, num_hiddens, device):\n    num_inputs = num_outputs = vocab_size\n\n    def normal(shape):\n        return torch.randn(size=shape, device=device)*0.01\n\n    def three():\n        return (normal((num_inputs, num_hiddens)),\n                normal((num_hiddens, num_hiddens)),\n                d2l.zeros(num_hiddens, device=device))\n\n    W_xi, W_hi, b_i = three()  # 输入门参数\n    W_xf, W_hf, b_f = three()  # 遗忘门参数\n    W_xo, W_ho, b_o = three()  # 输出门参数\n    W_xc, W_hc, b_c = three()  # 候选记忆元参数\n    # 输出层参数\n    W_hq = normal((num_hiddens, num_outputs))\n    b_q = d2l.zeros(num_outputs, device=device)\n    # 附加梯度\n    params = [W_xi, W_hi, b_i, W_xf, W_hf, b_f, W_xo, W_ho, b_o, W_xc, W_hc,\n              b_c, W_hq, b_q]\n    for param in params:\n        param.requires_grad_(True)\n    return params\n', 'def init_lstm_state(batch_size, num_hiddens, device):\n    return (torch.zeros((batch_size, num_hiddens), device=device),\n            torch.zeros((batch_size, num_hiddens), device=device))\n', 'def lstm(inputs, state, params):\n    [W_xi, W_hi, b_i, W_xf, W_hf, b_f, W_xo, W_ho, b_o, W_xc, W_hc, b_c,\n     W_hq, b_q] = params\n    (H, C) = state\n    outputs = []\n    for X in inputs:\n        I = torch.sigmoid((X @ W_xi) + (H @ W_hi) + b_i)\n        F = torch.sigmoid((X @ W_xf) + (H @ W_hf) + b_f)\n        O = torch.sigmoid((X @ W_xo) + (H @ W_ho) + b_o)\n        C_tilda = torch.tanh((X @ W_xc) + (H @ W_hc) + b_c)\n        C = F * C + I * C_tilda\n        H = O * torch.tanh(C)\n        Y = (H @ W_hq) + b_q\n        outputs.append(Y)\n    return torch.cat(outputs, dim=0), (H, C)\n', 'vocab_size, num_hiddens, device = len(vocab), 64, d2l.try_gpu()\nnum_epochs, lr = 100, 1\nmodel = d2l.RNNModelScratch(len(vocab), num_hiddens, device, get_params, init_gru_state, gru)\nd2l.train_ch8(model, train_iter, vocab, lr, num_epochs, device)', 'model = d2l.RNNModelScratch(len(vocab), num_hiddens, device, get_lstm_params, init_lstm_state, lstm)\nd2l.train_ch8(model, train_iter, vocab, lr, num_epochs, device)', 'model = d2l.RNNModel(nn.GRU(vocab_size, num_hiddens), len(vocab))\nd2l.train_ch8(model, train_iter, vocab, lr, num_epochs, device)', 'model = d2l.RNNModel(nn.LSTM(vocab_size, num_hiddens), len(vocab))\nd2l.train_ch8(model, train_iter, vocab, lr, num_epochs, device)']
